class EncryptionUtils:
    ALPHA_UPPER_OFFSET = 65
    ALPHA_LOWER_OFFSET = 97
    ALPHABET_SIZE = 26
    FENCE_EMPTY_CHAR = '\n'

    def __init__(self, key):
        self.key = key

    def caesar_cipher(self, plaintext, shift):
        return ''.join(self._encrypt_char_caesar(char, shift) for char in plaintext)

    def _encrypt_char_caesar(self, char, shift):
        if not char.isalpha():
            return char
        ascii_offset = self.ALPHA_UPPER_OFFSET if char.isupper() else self.ALPHA_LOWER_OFFSET
        return chr((ord(char) - ascii_offset + shift) % self.ALPHABET_SIZE + ascii_offset)

    def vigenere_cipher(self, plain_text):
        return ''.join(self._encrypt_char_vigenere(char, key_index) for key_index, char in keyed_chars(plain_text, self.key))

    @staticmethod
    def keyed_chars(plain_text, key):
        key_index = 0
        for char in plain_text:
            if char.isalpha():
                yield char, key_index
                key_index += 1
            else:
                yield char, None

    def _encrypt_char_vigenere(self, char, key_index):
        if not char.isalpha():
            return char
        shift = self._get_vigenere_shift(key_index)
        encrypted_lower = chr((ord(char.lower()) - self.ALPHA_LOWER_OFFSET + shift) % self.ALPHABET_SIZE + self.ALPHA_LOWER_OFFSET)
        return encrypted_lower.upper() if char.isupper() else encrypted_lower

    def _get_vigenere_shift(self, key_index):
        key_char = self.key[key_index % len(self.key)].lower()
        return ord(key_char) - self.ALPHA_LOWER_OFFSET

    def rail_fence_cipher(self, plain_text, rails):
        fence = self._build_fence(plain_text, rails)
        return self._read_fence(fence, len(plain_text))

    def _build_fence(self, plain_text, rails):
        fence = [[self.FENCE_EMPTY_CHAR for _ in range(len(plain_text))] for _ in range(rails)]
        direction = -1
        row, col = 0, 0

        for char in plain_text:
            if row == 0 or row == rails - 1:
                direction = -direction
            fence[row][col] = char
            col += 1
            row += direction
        return fence

    def _read_fence(self, fence, text_length):
        return ''.join(
            fence[i][j]
            for i in range(len(fence))
            for j in range(text_length)
            if fence[i][j] != self.FENCE_EMPTY_CHAR
        )
